public static int maxRegions(int N) {
    if (N <= 0) {
        // Zero triangles: the whole plane is one region
        return 1;
    }
    // For the maximum number of regions contributed by triangles,
    // the first triangle creates 2 regions (inside and outside).
    // Every additional triangle can, in the optimal arrangement,
    // increase the number of regions by exactly 6.
    long regions = 2L + 6L * (N - 1L);
    if (regions > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Number of regions exceeds integer limits");
    }
    return (int) regions;
}

