public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n < 0 || start == null || end == null || paths == null) {
            return "cannot be travelled";
        }
        // Ensure start and end contain at least one element
        if (start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }
        int startNode = start[0];
        int endNode = end[0];
        if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
            return "cannot be travelled";
        }

        // Build adjacency list
        List<List<Integer>> graph = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] path : paths) {
            if (path == null || path.length < 2) {
                continue; // ignore malformed path
            }
            int u = path[0];
            int v = path[1];
            if (u < 0 || u >= n || v < 0 || v >= n) {
                continue; // ignore invalid indices
            }
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        // BFS
        boolean[] visited = new boolean[n];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(startNode);
        visited[startNode] = true;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur == endNode) {
                return "can be travelled";
            }
            for (int neighbor : graph.get(cur)) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.offer(neighbor);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

