public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Input date string cannot be null or empty");
    }
    try {
        java.time.format.DateTimeFormatter inputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy", java.util.Locale.ENGLISH);
        java.time.LocalDate parsedDate = java.time.LocalDate.parse(date.trim(), inputFormatter);

        java.time.format.DateTimeFormatter outputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy", java.util.Locale.ENGLISH);
        String formattedDate = parsedDate.format(outputFormatter);

        java.time.DayOfWeek dayOfWeek = parsedDate.getDayOfWeek();
        String weekday = dayOfWeek.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return formattedDate + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid date format, expected 'MM dd yyyy'", e);
    }
}

