public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int k = (int) Math.floor(n * 0.05);
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    int count = n - 2 * k;
    return count == 0 ? 0.0 : sum / (double) count;
}

