public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    int upper = k / 2;
    for (int r = 1; r < upper; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    // If k is even, remainder k/2 also needs to pair with itself
    if (k % 2 == 0) {
        if (freq[upper] % 2 != 0) {
            return false;
        }
    }
    return true;
}

