public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    // sets[k] will contain all achievable sums with exactly k elements
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] sets = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        sets[i] = new java.util.HashSet<>();
    }
    sets[0].add(0);

    // Build subset sum sets
    for (int num : nums) {
        // iterate k backwards to avoid using the same number twice
        for (int k = n - 1; k >= 0; k--) {
            if (sets[k].isEmpty()) continue;
            java.util.HashSet<Integer> current = sets[k];
            java.util.HashSet<Integer> next = sets[k + 1];
            for (int s : current) {
                next.add(s + num);
            }
        }
    }

    // Check for any valid split
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) continue;
        int targetSum = (totalSum * k) / n;
        if (sets[k].contains(targetSum)) {
            return true;
        }
    }
    return false;
}

