public boolean hasAllCodes(String s, int k) {
    if (k <= 0) {
        return true;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int required = 1 << k;
    boolean[] seen = new boolean[required];
    int count = 0;
    int mask = required - 1;
    int code = 0;
    // build initial code from first k characters
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    if (!seen[code]) {
        seen[code] = true;
        count++;
    }
    for (int i = k; i < n; i++) {
        code = ((code << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == required) {
                return true;
            }
        }
    }
    return count == required;
}

