public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int unmatchedLeft = 0; // count of unmatched '('
    int requiredOpen = 0; // number of '(' to insert to match unmatched ')'
    for (char ch : s.toCharArray()) {
        if (ch == '(') {
            unmatchedLeft++;
        } else if (ch == ')') {
            if (unmatchedLeft > 0) {
                unmatchedLeft--;
            } else {
                requiredOpen++;
            }
        } else {
            throw new IllegalArgumentException("Invalid character in input: " + ch);
        }
    }
    return unmatchedLeft + requiredOpen;
}

