public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    if (k < n || k > 26L * n) {
        throw new IllegalArgumentException("k is out of the valid range");
    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
