public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    if (low <= 0) {
        result.add(0);
    }
    Queue<Long> queue = new ArrayDeque<>();
    for (int d = 1; d <= 9; d++) {
        queue.offer((long) d);
    }
    while (!queue.isEmpty()) {
        long cur = queue.poll();
        if (cur > high) {
            continue;
        }
        if (cur >= low) {
            result.add((int) cur);
        }
        int last = (int) (cur % 10);
        if (last > 0) {
            long next = cur * 10 + (last - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (last < 9) {
            long next = cur * 10 + (last + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

